	"os"
)

const (
	_A = 'a'
	_B = 'b'
	_C = 'c'
)

var reader = bufio.NewReader(os.Stdin)
var writer = bufio.NewWriter(os.Stdout)

func main() {
	defer writer.Flush()

	var n, k int
	fmt.Fscan(reader, &n, &k)

	var s, t string
	fmt.Fscan(reader, &s)
	fmt.Fscan(reader, &t)

	result := findBestScoreCanMake(s, t, k)
	fmt.Fprintln(writer, result)
}

func findBestScoreCanMake(s, t string, movesN int) int {
	if len(t) != 2 {
		panic("len(t) must be 2")
	}
	if t[0] == t[1] {
		tChar := t[0]
		tCharCount := 0
		for i := 0; i < len(s); i++ {
			if s[i] == tChar {
				tCharCount++
			}
		}
		tCharCount += movesN
		if tCharCount > len(s) {
			tCharCount = len(s)
		}
		return tCharCount * (tCharCount - 1) / 2
	}

	// map s to A/B/C
	mapped := make([]rune, len(s))
	for i, ch := range s {
		if ch == rune(t[0]) {
			mapped[i] = _A
		} else if ch == rune(t[1]) {
			mapped[i] = _B
		} else {
			mapped[i] = _C
		}
	}
	sRunes := string(mapped)

	_, bIndices, cIndices := computeABCIndices(sRunes)

	bestScore := -int(^uint(0)>>1)

	maxCStart := len(cIndices)
	if maxCStart > movesN {
		maxCStart = movesN
	}
	for cStart := 0; cStart <= maxCStart; cStart++ {
		cStartMovesSpent := cStart
		movesRemain := movesN - cStartMovesSpent

		maxBStart := len(bIndices)
		if maxBStart > movesRemain {
			maxBStart = movesRemain
		}
		for bStart := 0; bStart <= maxBStart; bStart++ {
			bStartMovesSpent := bStart
			movesSpent := cStartMovesSpent + bStartMovesSpent
			movesRemain = movesN - movesSpent

			newS := []rune(sRunes)
			for iIC := 0; iIC < cStart; iIC++ {
				iC := cIndices[iIC]
				newS[iC] = _A
			}
			for iIB := 0; iIB < bStart; iIB++ {
				iB := bIndices[iIB]
				newS[iB] = _A
			}

			currBestScore := findBestScoreCanMakeWithFixedStarts(newS, movesRemain)
			if currBestScore > bestScore {
				bestScore = currBestScore
			}
		}
	}
	return bestScore
}

func computeABCIndices(s string) ([]int, []int, []int) {
	aIndices := []int{}
	bIndices := []int{}
	cIndices := []int{}
	for i, ch := range s {
		if ch == _A {
			aIndices = append(aIndices, i)
		} else if ch == _B {
			bIndices = append(bIndices, i)
		} else {
			if ch != _C {
				panic("char must be C")
			}
			cIndices = append(cIndices, i)
		}
	}
	return aIndices, bIndices, cIndices
}

func findBestScoreCanMakeWithFixedStarts(s []rune, movesN int) int {
	bestScore := -int(^uint(0)>>1)

	aIndices, bIndices, cIndices := computeABCIndices(string(s))

	aN := len(aIndices)
	cN := len(cIndices)
	_ = bIndices
	_ = cN

	maxAStop := len(aIndices)
	maxCStop := len(cIndices)

	getCStopByMovesRemain := func(movesRemain int) int {
		minCStop := maxCStop - movesRemain
		if minCStop < 0 {
			minCStop = 0
		}
		cStop := minCStop
		return cStop
	}

	firstCStop := getCStopByMovesRemain(movesN)
	newS := getCurrS(s, aIndices, maxAStop, cIndices, firstCStop)
	currScore := getCurrScoreSlowWay(newS)

	if currScore > bestScore {
		bestScore = currScore
	}

	oldABefore := computeABefore(newS)
	tmp := make([]rune, len(newS))
	copy(tmp, newS)
	for i, ch := range tmp {
		if ch == _C {
			tmp[i] = _B
		}
	}
	oldBAfterIfAllCAreB := computeBAfter(string(tmp))

	currBToCBeforeA := 0
	currAToBAfterC := 0

	var prevCStop *int
	cStop := firstCStop
	cStopMovesSpent := maxCStop - cStop
	_ = cStopMovesSpent

	minAStop := maxAStop - movesN
	if minAStop < 0 {
		minAStop = 0
	}
	for aStop := maxAStop - 1; aStop >= minAStop; aStop-- {
		aStopMovesSpent := maxAStop - aStop
		movesSpent := aStopMovesSpent
		movesRemain := movesN - movesSpent

		currAIndex := aIndices[aStop]
		currBToC := cStop
		if currBToCBeforeA < currBToC && currBToCBeforeA < len(cIndices) && cIndices[currBToCBeforeA] < currAIndex {
			for currBToCBeforeA < currBToC && currBToCBeforeA < len(cIndices) && cIndices[currBToCBeforeA] < currAIndex {
				currBToCBeforeA++
			}
		} else if currBToCBeforeA > 0 && cIndices[currBToCBeforeA-1] > currAIndex {
			for currBToCBeforeA > 0 && cIndices[currBToCBeforeA-1] > currAIndex {
				currBToCBeforeA--
			}
		}

		prevAStopMovesSpent := aStopMovesSpent - 1
		currBToCAfterA := currBToC - currBToCBeforeA
		newBAfter := prevAStopMovesSpent - currBToCAfterA
		bAfter := oldBAfterIfAllCAreB[currAIndex] + newBAfter
		currScore -= bAfter
		currScore += oldABefore[currAIndex]

		prev := cStop
		prevCStop = &prev
		cStop = getCStopByMovesRemain(movesRemain)
		cStopMovesSpent = maxCStop - cStop
		_ = cStopMovesSpent

		if *prevCStop == cStop {
		} else if cStop-*prevCStop == 1 {
			prevCIndex := cIndices[*prevCStop]
			currAToB := aN - aStop
			if currAToBAfterC < currAToB && currAToBAfterC < aN && aIndices[aN-(currAToBAfterC+1)] > prevCIndex {
				for currAToBAfterC < currAToB && currAToBAfterC < aN && aIndices[aN-(currAToBAfterC+1)] > prevCIndex {
					currAToBAfterC++
				}
			} else if currAToBAfterC > 0 && aIndices[aN-currAToBAfterC] < prevCIndex {
				for currAToBAfterC > 0 && aIndices[aN-currAToBAfterC] < prevCIndex {
					currAToBAfterC--
				}
			}

			aToBBefore := currAToB - currAToBAfterC
			currABefore := oldABefore[prevCIndex] - aToBBefore
			currScore -= currABefore
		}

		if currScore > bestScore {
			bestScore = currScore
		}
	}

	return bestScore
}

func getCurrS(s []rune, aIndices []int, aStop int, cIndices []int, cStop int) []rune {
	res := make([]rune, len(s))
	copy(res, s)

	for iIA := 0; iIA < aStop; iIA++ {
		iA := aIndices[iIA]
		res[iA] = _A
	}
	for iIA := aStop; iIA < len(aIndices); iIA++ {
		iA := aIndices[iIA]
		res[iA] = _B
	}
	for iIC := 0; iIC < cStop; iIC++ {
		iC := cIndices[iIC]
		res[iC] = _C
	}
	for iIC := cStop; iIC < len(cIndices); iIC++ {
		iC := cIndices[iIC]
		res[iC] = _B
	}
	return res
}

func getCurrScoreSlowWay(s []rune) int {
	currScore := 0
	aAccumulated := 0
	for _, ch := range s {
		if ch == _A {
			aAccumulated++
		} else if ch == _B {
			currScore += aAccumulated
		}
	}
	return currScore
}

func computeABefore(s []rune) []int {
	n := len(s)
	acc := make([]int, n)
	sum := 0
	for i, ch := range s {
		if ch == _A {
			sum++
		}
		acc[i] = sum
	}
	result := make([]int, n)
	result[0] = 0
	for i := 1; i < n; i++ {
		result[i] = acc[i-1]
	}
	return result
}

func computeBAfter(s string) []int {
	n := len(s)
	acc := make([]int, n)
	sum := 0
	for i := n - 1; i >= 0; i-- {
		if s[i] == byte(_B) {
			sum++
		}
		acc[i] = sum
	}
	result := make([]int, n)
	for i := 0; i < n-1; i++ {
		result[i] = acc[i+1]
	}
	result[n-1] = 0
	return result
}

