func nextInt() int {
	scanner.Scan()
	b := scanner.Bytes()
	n := 0
	sign := 1
	i := 0
	if len(b) > 0 && (b[0] == '-' || b[0] == '+') {
		if b[0] == '-' {
			sign = -1
		}
		i++
	}
	for ; i < len(b); i++ {
		n = n*10 + int(b[i]-'0')
	}
	return sign * n
}

func nextString() string {
	scanner.Scan()
	return scanner.Text()
}

func main() {
	scanner.Split(bufio.ScanWords)
	n := nextInt()
	_ = n
	k := nextInt()
	s := nextString()
	t := nextString()
	result := find_best_score_can_make(s, t, k)
	fmt.Println(result)
}

func find_best_score_can_make(s string, t string, moves_n int) int {
	if len(t) != 2 {
		panic("len(t) must be 2")
	}
	if t[0] == t[1] {
		tChar := t[0]
		tCharCount := 0
		for i := 0; i < len(s); i++ {
			if s[i] == tChar {
				tCharCount++
			}
		}
		tCharCount += moves_n
		if tCharCount > len(s) {
			tCharCount = len(s)
		}
		return tCharCount * (tCharCount - 1) / 2
	}

	mapped := make([]rune, len(s))
	for i, ch := range s {
		if ch == rune(t[0]) {
			mapped[i] = _A
		} else if ch == rune(t[1]) {
			mapped[i] = _B
		} else {
			mapped[i] = _C
		}
	}
	sRunes := string(mapped)

	aIndices, bIndices, cIndices := _compute_abc_indices(sRunes)

	bestScore := -1 << 60

	maxCStart := moves_n
	if len(cIndices) < maxCStart {
		maxCStart = len(cIndices)
	}
	for cStart := 0; cStart <= maxCStart; cStart++ {
		cStartMovesSpent := cStart
		movesSpent := cStartMovesSpent
		movesRemain := moves_n - movesSpent

		maxBStart := movesRemain
		if len(bIndices) < maxBStart {
			maxBStart = len(bIndices)
		}
		for bStart := 0; bStart <= maxBStart; bStart++ {
			bStartMovesSpent := bStart
			movesSpent = cStartMovesSpent + bStartMovesSpent
			movesRemain = moves_n - movesSpent

			newS := []rune(sRunes)
			for iIC := 0; iIC < cStart; iIC++ {
				iC := cIndices[iIC]
				newS[iC] = _A
			}
			for iIB := 0; iIB < bStart; iIB++ {
				iB := bIndices[iIB]
				newS[iB] = _A
			}

			currBestScore := _find_best_score_can_make_with_fixed_starts(newS, movesRemain)
			if currBestScore > bestScore {
				bestScore = currBestScore
			}
		}
	}

	return bestScore
}

func _compute_abc_indices(s string) ([]int, []int, []int) {
	aIndices := []int{}
	bIndices := []int{}
	cIndices := []int{}
	for i, ch := range s {
		if ch == _A {
			aIndices = append(aIndices, i)
		} else if ch == _B {
			bIndices = append(bIndices, i)
		} else {
			if ch != _C {
				panic("char must be c")
			}
			cIndices = append(cIndices, i)
		}
	}
	return aIndices, bIndices, cIndices
}

func _find_best_score_can_make_with_fixed_starts(s []rune, moves_n int) int {
	bestScore := -1 << 60

	aIndices, bIndices, cIndices := _compute_abc_indices(string(s))

	aN := len(aIndices)
	cN := len(cIndices)
	_ = cN

	maxAStop := len(aIndices)
	maxCStop := len(cIndices)

	get_c_stop_by_moves_remain := func(movesRemain int) int {
		minCStop := maxCStop - movesRemain
		if minCStop < 0 {
			minCStop = 0
		}
		cStop := minCStop
		return cStop
	}

	firstCStop := get_c_stop_by_moves_remain(moves_n)
	newS := _get_curr_s(s, aIndices, maxAStop, cIndices, firstCStop)
	currScore := _get_curr_score_slow_way(newS)

	if currScore > bestScore {
		bestScore = currScore
	}

	oldABefore := _compute_a_before(newS)
	tmp := make([]rune, len(newS))
	for i, ch := range newS {
		if ch == _C {
			tmp[i] = _B
		} else {
			tmp[i] = ch
		}
	}
	oldBAfterIfAllCAreB := _compute_b_after(string(tmp))

	currBToCBeforeA := 0
	currAToBAfterC := 0

	var prevCStop *int
	cStop := firstCStop
	cStopMovesSpent := maxCStop - cStop
	_ = cStopMovesSpent

	minAStop := maxAStop - moves_n
	if minAStop < 0 {
		minAStop = 0
	}
	for aStop := maxAStop - 1; aStop >= minAStop; aStop-- {
		aStopMovesSpent := maxAStop - aStop
		movesSpent := aStopMovesSpent
		movesRemain := moves_n - movesSpent

		currAIndex := aIndices[aStop]
		currBToC := cStop
		if currBToCBeforeA < currBToC && currBToCBeforeA < len(cIndices) && cIndices[currBToCBeforeA] < currAIndex {
			for currBToCBeforeA < currBToC && currBToCBeforeA < len(cIndices) && cIndices[currBToCBeforeA] < currAIndex {
				currBToCBeforeA++
			}
		} else if currBToCBeforeA > 0 && cIndices[currBToCBeforeA-1] > currAIndex {
			for currBToCBeforeA > 0 && cIndices[currBToCBeforeA-1] > currAIndex {
				currBToCBeforeA--
			}
		}

		prevAStopMovesSpent := aStopMovesSpent - 1
		currBToCAfterA := currBToC - currBToCBeforeA
		newBAfter := prevAStopMovesSpent - currBToCAfterA
		bAfter := oldBAfterIfAllCAreB[currAIndex] + newBAfter
		currScore -= bAfter
		currScore += oldABefore[currAIndex]

		prevCStopVal := cStop
		prevCStop = &prevCStopVal
		cStop = get_c_stop_by_moves_remain(movesRemain)
		cStopMovesSpent = maxCStop - cStop

		if cStop-*prevCStop == 1 {
			prevCIndex := cIndices[*prevCStop]
			currAToB := aN - aStop
			if currAToBAfterC < currAToB && currAToBAfterC < aN && aIndices[aN-(currAToBAfterC+1)] > prevCIndex {
				for currAToBAfterC < currAToB && currAToBAfterC < aN && aIndices[aN-(currAToBAfterC+1)] > prevCIndex {
					currAToBAfterC++
				}
			} else if currAToBAfterC > 0 && aIndices[aN-currAToBAfterC] < prevCIndex {
				for currAToBAfterC > 0 && aIndices[aN-currAToBAfterC] < prevCIndex {
					currAToBAfterC--
				}
			}

			aToBBefore := currAToB - currAToBAfterC
			currABefore := oldABefore[prevCIndex] - aToBBefore
			currScore -= currABefore
		}

		if currScore > bestScore {
			bestScore = currScore
		}
	}

	return bestScore
}

func _get_curr_s(s []rune, aIndices []int, aStop int, cIndices []int, cStop int) []rune {
	newS := make([]rune, len(s))
	copy(newS, s)
	for iIA := 0; iIA < aStop; iIA++ {
		iA := aIndices[iIA]
		newS[iA] = _A
	}
	for iIA := aStop; iIA < len(aIndices); iIA++ {
		iA := aIndices[iIA]
		newS[iA] = _B
	}
	for iIC := 0; iIC < cStop; iIC++ {
		iC := cIndices[iIC]
		newS[iC] = _C
	}
	for iIC := cStop; iIC < len(cIndices); iIC++ {
		iC := cIndices[iIC]
		newS[iC] = _B
	}
	return newS
}

func _get_curr_score_slow_way(s []rune) int {
	currScore := 0
	aAccumulated := 0
	for _, ch := range s {
		if ch == _A {
			aAccumulated++
		} else if ch == _B {
			currScore += aAccumulated
		}
	}
	return currScore
}

func _compute_a_before(s []rune) []int {
	n := len(s)
	acc := make([]int, n)
	sum := 0
	for i, ch := range s {
		if ch == _A {
			sum++
		}
		acc[i] = sum
	}
	result := make([]int, n)
	result[0] = 0
	for i := 1; i < n; i++ {
		result[i] = acc[i-1]
	}
	return result
}

func _compute_b_after(s string) []int {
	n := len(s)
	acc := make([]int, n)
	sum := 0
	for i := n - 1; i >= 0; i-- {
		if s[i] == byte(_B) {
			sum++
		}
		acc[i] = sum
	}
	result := make([]int, n)
	for i := 0; i < n-1; i++ {
		result[i] = acc[i+1]
	}
	result[n-1] = 0
	return result
}
